  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (t.length !== n) fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        if (events.length) fail('declarations must come before the first event')
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        let p
        if (d === 'bucket') {
          const capacity = int(t[2], 'capacity', 1)
          const refill = int(t[3], 'refill', 0)
          const per = int(t[4], 'per', 1)
          p = { type: 'bucket', name: t[1], capacity, refill, per }
        } else {
          p = { type: 'window', name: t[1], limit: int(t[2], 'limit', 0), span: int(t[3], 'span', 1) }
        }
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], p)
      } else if (d === 'route') {
        if (t.length < 3) fail('expected route <prefix> <policy>...')
        if (events.length) fail('declarations must come before the first event')
        if (!NAME.test(t[1])) fail(`invalid route prefix ${t[1]}`)
        for (const n of t.slice(2)) if (!policies.has(n)) fail(`unknown policy ${n}`)
        if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
        routes.set(t[1], t.slice(2).map((n) => policies.get(n)))
      } else if (d === 'event') {
        if (t.length !== 3) fail('expected event <tick> <key>')
        const tick = int(t[1], 'tick', 0)
        if (!NAME.test(t[2])) fail(`invalid key ${t[2]}`)
        if (last !== null && tick < last) fail(`tick ${tick} is before tick ${last}`)
        last = tick
        events.push({ tick, key: t[2] })
      } else fail(`unknown directive ${d}`)
    } catch (e) {
      if (e instanceof Fail) e.message = `error: line ${i + 1}: ${e.message}`
      throw e
    }
  })
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map() // policy -> key -> state
  const stateOf = (p, key) => {
    let m = states.get(p)
    if (!m) states.set(p, (m = new Map()))
    let s = m.get(key)
    if (!s) {
      s = p.type === 'bucket' ? { scaled: p.capacity * p.per, at: null } : { ticks: [] }
      m.set(key, s)
    }
    return s
  }
  const out = []
  for (const { tick, key } of events) {
    let best = null
    for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    if (best === null) { out.push({ tick, key, deny: null }); continue }
    const ps = routes.get(best)
    for (const p of ps) {
      const s = stateOf(p, key)
      if (p.type === 'bucket') {
        if (s.at !== null && tick > s.at) {
          s.scaled += p.refill * (tick - s.at)
          const cap = p.capacity * p.per
          if (s.scaled > cap) s.scaled = cap
        }
        s.at = tick
      } else {
        const cut = tick - p.span
        s.ticks = s.ticks.filter((x) => x > cut)
      }
    }
    const ok = (p) => {
      const s = stateOf(p, key)
      return p.type === 'bucket' ? s.scaled >= p.per : BigInt(s.ticks.length) < p.limit
    }
    const refused = ps.find((p) => !ok(p))
    if (!refused) {
      for (const p of ps) {
        const s = stateOf(p, key)
        if (p.type === 'bucket') s.scaled -= p.per
        else s.ticks.push(tick)
      }
    }
    out.push({ tick, key, deny: refused ? refused.name : null, denied: !!refused })
  }
  return out
}

