try {
  const model = parse(readFileSync(0, 'utf8'))
  const res = run(model)
  const lines = []
  if (mode === 'replay') {
    for (const r of res) lines.push(`${r.tick} ${r.key} ${r.denied ? 'deny ' + r.deny : 'allow'}`)
  } else {
    const per = new Map()
    let a = 0, d = 0
    for (const r of res) {
      const c = per.get(r.key) || { a: 0, d: 0 }
      if (r.denied) { c.d++; d++ } else { c.a++; a++ }
      per.set(r.key, c)
    }
